"""Bounded research tools."""

from __future__ import annotations

import contextlib
import math
from collections.abc import Sequence
from dataclasses import dataclass, field, replace
from typing import Any

from codey.knowledge.concept_schema import clean_relations, normalize_concept
from codey.knowledge.model import KnowledgeMutation, KnowledgeObject, canonical_json
from codey.knowledge.note import NOTE_STATUSES, NOTE_TYPES, KnowledgeNote, is_safe_id
from codey.knowledge.recall import KnowledgeAccess, KnowledgeHit, render_recall
from codey.knowledge.store import KnowledgeStore
from codey.research.ledger import EvidencePreparation, ResearchLedger
from codey.research.source_gateway import (
    OPEN_DEFAULT_LIMIT,
    OPEN_MAX_LIMIT,
    OPEN_MIN_LIMIT,
    SEARCH_LIMIT,
    ResearchSourceGateway,
)
from codey.research.source_rendering import render_opened_source
from codey.research.source_search import (
    SOURCE_SEARCH_DEFAULT_LIMIT,
    render_results,
)
from codey.research.staging import StagedKnowledgeChanges, StagedKnowledgeStore
from codey.research.url_selection import source_candidate_skip_reason

_CITED_TYPES = {"fact", "conclusion", "decision", "implementation", "verification", "synthesis", "project_note"}


@dataclass(frozen=True)
class ResearchToolOutput:
    """Model-visible text plus the full text reserved for durable receipts."""

    model_text: str
    receipt_text: str = ""
    read_passages: tuple[dict[str, Any], ...] = ()
    read_observation: dict[str, Any] = field(default_factory=dict)
    ok: bool = field(kw_only=True)
    knowledge_search_empty: bool = field(default=False, kw_only=True)

    def __post_init__(self) -> None:
        if type(self.ok) is not bool:
            raise TypeError("research output ok must be an exact boolean")


@dataclass
class ResearchTools:
    search: Any
    store: Any
    changes: Any
    diagnostics: object | None = None
    session_id: str = ""
    project: str = ""
    sources_read: set[str] = field(default_factory=set)
    search_result_urls: set[str] = field(default_factory=set)
    grounded_ids: set[str] = field(default_factory=set)
    created_ids: list[str] = field(default_factory=list)
    updated_ids: list[str] = field(default_factory=list)
    synthesis_id: str = ""
    links_created: int = 0
    ledger: ResearchLedger = field(default_factory=ResearchLedger)
    evidence_only: bool = False
    finding_report: bool = False
    local_submission: bool = False
    coherent_passages: bool = False

    def create_staged(self) -> ResearchTools:
        staged_store = StagedKnowledgeStore(self.store) if self.store is not None else None
        staged_changes = StagedKnowledgeChanges(self.changes) if self.changes is not None else None
        return ResearchTools(
            search=self.search,
            store=staged_store,
            changes=staged_changes,
            diagnostics=self.diagnostics,
            session_id=self.session_id,
            project=self.project,
            sources_read=set(self.sources_read) | self.ledger.final_url_set(),
            search_result_urls=set(self.search_result_urls),
            grounded_ids=set(self.grounded_ids),
            created_ids=list(self.created_ids),
            updated_ids=list(self.updated_ids),
            synthesis_id=self.synthesis_id,
            links_created=self.links_created,
            ledger=self.ledger.clone(),
            evidence_only=self.evidence_only,
            finding_report=self.finding_report,
            local_submission=self.local_submission,
            coherent_passages=self.coherent_passages,
        )

    def commit_staged(self, staged: ResearchTools) -> None:
        if isinstance(staged.store, StagedKnowledgeStore):
            if self.store is None:
                raise ValueError("cannot commit knowledge into an unavailable store")
            staged.store.commit_to(self.store, changes=self.changes)
        self.sources_read.update(staged.sources_read)
        self.search_result_urls.update(staged.search_result_urls)
        self.grounded_ids.update(staged.grounded_ids)
        self.created_ids = list(dict.fromkeys(self.created_ids + staged.created_ids))
        self.updated_ids = list(dict.fromkeys(self.updated_ids + staged.updated_ids))
        if staged.synthesis_id:
            self.synthesis_id = staged.synthesis_id
        self.links_created = max(self.links_created, staged.links_created)
        self.ledger = staged.ledger

    @property
    def gateway(self) -> ResearchSourceGateway:
        """Acquisition spine over this tool's provider and ledger.

        Built fresh per access (no I/O): staged clones pick up their own
        ledger automatically, so staging semantics never drift.
        """
        return ResearchSourceGateway(
            search_provider=self.search,
            ledger=self.ledger,
            on_failure=self._record_failure,
        )

    def web_search(self, query: str) -> ResearchToolOutput:
        query = (query or "").strip()
        if not query:
            return ResearchToolOutput("ERROR: web_search needs a non-empty query", ok=False)
        outcome = self.gateway.search(query, SEARCH_LIMIT)
        if outcome.error:
            return ResearchToolOutput(f"ERROR: {outcome.error}", ok=False)
        results = outcome.hits
        if not results:
            return ResearchToolOutput("no results", ok=True)
        lines: list[str] = []
        skipped = 0
        for r in results:
            url = str(r.get("url") or "")
            if url:
                self.search_result_urls.add(url)
            if source_candidate_skip_reason(url):
                skipped += 1
                continue
            snippet = _clip_tail(str(r.get("snippet") or ""), 200)
            i = len(lines) + 1
            lines.append(f"{i}. {r.get('title')}\n   {url}\n   {snippet}".rstrip())
        if not lines and skipped:
            return ResearchToolOutput(f"no useful non-landing results; skipped {skipped} low-value landing result(s)", ok=True)
        return ResearchToolOutput("\n".join(lines), ok=True)

    def open_url(self, url: str, offset: int = 0, limit: int = OPEN_DEFAULT_LIMIT, pages: str = "") -> ResearchToolOutput:
        """Open a page once: bounded window for the model, full text for receipts."""
        return self._open_document(url, offset=offset, limit=limit, pages=pages)

    def _open_document(
        self, url: str, offset: int = 0, limit: int = OPEN_DEFAULT_LIMIT, pages: str = ""
    ) -> ResearchToolOutput:
        outcome = self.gateway.open(url, offset=offset, limit=limit, pages=pages)
        if outcome.status == "error":
            return ResearchToolOutput(f"ERROR: {outcome.detail}", ok=False)
        if outcome.status == "skipped":
            return ResearchToolOutput(f"SKIPPED: {outcome.detail}", ok=False)
        document = outcome.document
        assert document is not None
        self.sources_read.update(outcome.read_urls)
        offset = max(0, _as_int(offset, 0))
        if offset >= len(document.text):
            return ResearchToolOutput(
                f"ERROR: source offset={offset} is at or beyond the end of available extracted text "
                f"(length={len(document.text)} characters). No passage was read. "
                "Do not advance the offset; use source_search on an earlier section or investigate another source.", ok=False)
        # Leave room for exact passage labels, metadata and source boundaries.
        limit = min(OPEN_MAX_LIMIT - 2500, max(OPEN_MIN_LIMIT, _as_int(limit, OPEN_DEFAULT_LIMIT)))
        from codey.research.ledger_receipts import ledger_observation
        from codey.research.passages import describe_document_window, render_passage_window, restore_passages

        snapshot = ResearchLedger()
        snapshot.record_open_document(document)
        observation = ledger_observation(snapshot, "open", url=document.final_url)
        source = snapshot.source_record_for_url(document.final_url)
        assert source is not None
        passages = describe_document_window(document, source.text_hash, offset, limit, coherent=self.coherent_passages)
        if not passages:
            return ResearchToolOutput("ERROR: the requested source window contains no readable text; no passage was read.",
                                      ok=False)
        window = render_passage_window(document, passages)
        next_offset = passages[-1]["end"]
        more = next_offset < len(document.text)
        body = render_opened_source(
            document,
            window,
            more_offset=next_offset if more else None,
            read_window=(passages[0]["start"], passages[-1]["end"]),
        )
        if len(body) > OPEN_MAX_LIMIT:
            # A clipped body must not authorize a partly unseen passage. Drop
            # whole trailing passages and rerender their accurate next offset.
            while len(passages) > 1 and len(body) > OPEN_MAX_LIMIT:
                next_offset = passages.pop()["start"]
                window = render_passage_window(document, passages)
                body = render_opened_source(document, window, more_offset=next_offset,
                    read_window=(passages[0]["start"], passages[-1]["end"]))
            if len(body) > OPEN_MAX_LIMIT:
                return ResearchToolOutput("ERROR: source metadata exceeds the readable window budget; no passage was read.",
                                          ok=False)
        restore_passages(self.ledger, observation, passages)
        full = render_opened_source(document, document.text)
        return ResearchToolOutput(model_text=body, receipt_text=full, read_passages=tuple(passages),
                                  read_observation=observation, ok=True)

    def source_search(self, url: str, query: str, limit: object = SOURCE_SEARCH_DEFAULT_LIMIT) -> ResearchToolOutput:
        outcome = self.gateway.search_inside(url, query, limit)
        if outcome.status == "needs_open":
            return ResearchToolOutput(f"NEEDS_OPEN: {outcome.detail}", ok=False)
        if outcome.status == "error":
            return ResearchToolOutput(f"ERROR: {outcome.detail}", ok=False)
        return ResearchToolOutput(render_results(list(outcome.hits)), ok=True)

    def knowledge_search(self, query: str, *, depth: int = 1) -> ResearchToolOutput:
        if self.store is None:
            return ResearchToolOutput("ERROR: knowledge store is unavailable", ok=False)
        query = (query or "").strip()
        if not query:
            return ResearchToolOutput("ERROR: knowledge_search needs a query", ok=False)
        hits = self.store.search(query, project=self.project, session_id=self.session_id, depth=depth)
        recalled = render_recall(hits, include_answer_refs=not (self.evidence_only or self.local_submission))
        rows = self.store.search_notes(query, project=self.project, session_id=self.session_id)
        if not rows:
            return ResearchToolOutput(recalled or "no local notes yet on this topic", ok=True,
                                      knowledge_search_empty=not hits)
        lines = [recalled] if recalled else []
        for row in rows:
            status = row.get("status") or "active"
            snippet = _clip_tail(str(row.get("snippet") or ""), 140)
            lines.append(f"[{row['type']}] {row['title']} (id={row['id']}, {status}; legacy document, verify evidence)\n   {snippet}".rstrip())
        return ResearchToolOutput("\n".join(lines), ok=True)

    def knowledge_read(self, note_id: str, *, revision: int | None = None, question_ref: str = "",
                       offset: int = 0, limit: int = 6000, whole_answer: bool = False) -> ResearchToolOutput:
        from codey.research.answer_contract import KNOWLEDGE_READ_GUIDANCE

        if self.store is None:
            return ResearchToolOutput("ERROR: knowledge store is unavailable", ok=False)
        binding = self.ledger.references.get(note_id)
        if binding:
            if revision is not None and revision != binding.revision:
                return ResearchToolOutput("ERROR: short reference is pinned to another revision", ok=False)
            note_id, revision = binding.object_id, binding.revision
        version = self.store.repository.read(note_id, revision)
        if version is not None:
            if not KnowledgeAccess(self.project, self.session_id, self.store.owner_id).allows(version):
                return ResearchToolOutput("ERROR: knowledge scope mismatch", ok=False)
            if version.value.kind in {"source", "evidence"}:
                from codey.research.knowledge_materials import read_material

                try:
                    return read_material(self, version, offset=offset, limit=limit)
                except (ValueError, TypeError, KeyError) as exc:
                    return ResearchToolOutput(f"ERROR: {exc}", ok=False)
            payload = version.to_dict()
            payload["content_complete"] = len(version.value.content) <= 12000
            payload["content"] = version.value.content[:12000]
            if whole_answer:
                payload["citation_guidance"] = KNOWLEDGE_READ_GUIDANCE
            elif version.value.kind in {"claim", "inference", "observation"} and payload["content_complete"]:
                from codey.research.references import bind_version

                payload["finding_ref"] = bind_version(self.ledger, version, question_ref=question_ref,
                    **({"acquisition": binding.acquisition, "note_id": binding.note_id,
                        "passage_ref": binding.passage_ref} if binding else {}))
                from codey.research.evidence_view import reference_evidence_preview

                payload.update(reference_evidence_preview(self.ledger, self.store, payload["finding_ref"],
                    project=self.project, session_id=self.session_id))
                payload["adoption"] = "Cite this fN only if adopted. It stays pinned and unreviewed; old answers are not evidence."
            return ResearchToolOutput(canonical_json(payload), ok=True)
        note = self.store.read_note((note_id or "").strip(), **({"revision": revision} if revision is not None else {}))
        if note is None:
            return ResearchToolOutput(self._missing_knowledge_identity(note_id), ok=False)
        if (note.project and note.project != self.project
                or not note.project and note.session_id and note.session_id != self.session_id):
            return ResearchToolOutput("ERROR: knowledge scope mismatch", ok=False)
        if note.type == "source" and any(s in self.sources_read for s in note.sources):
            self.grounded_ids.add(note.id)
        references: list[dict[str, Any]] = self.store.note_references(note.id, revision) if hasattr(self.store, "note_references") else []
        answer_refs = []
        claim_states = []
        access = KnowledgeAccess(self.project, self.session_id, self.store.owner_id)
        for ref in references:
            target = self.store.repository.read(str(ref["target"]), int(ref["revision"]))
            if target is not None and access.allows(target) and target.value.kind in {"claim", "inference", "question"}:
                answer_refs.append({"id": target.value.id, "revision": target.revision})
                claim_states.append({"id": target.value.id, "revision": target.revision,
                    "origin": target.value.origin, "status": target.value.status,
                    "interpretation_review": target.interpretation_review,
                    "dependencies_changed": target.dependencies_changed})
        automatic_refs = self.finding_report and note.id in (*self.created_ids, *self.updated_ids)
        preface = ("Document note; its note_id is not a done.knowledge_refs object id.\n"
                   "Answer reference candidates (use only versions actually adopted):\n"
                   + canonical_json({"knowledge_refs": answer_refs[:6]}) + "\n\n"
                   ) if answer_refs and not self.evidence_only and not automatic_refs and not self.local_submission else ""
        if whole_answer:
            preface = KNOWLEDGE_READ_GUIDANCE + "\n\n"
        elif self.local_submission and answer_refs:
            preface = ("Document note; read a linked knowledge object by its exact id and revision to obtain an fN "
                       "before explicitly selecting it with submit_research_answer.\n\n")
        if automatic_refs and not self.evidence_only and not whole_answer:
            preface = "Cite this saved finding by [finding_ref] only if adopted; the application resolves its exact versions.\n\n"
        preface += ("Document status describes the saved note, not semantic approval of its summary. "
                    "Inspect the linked claim and its exact evidence before adopting the wording.\n"
                    "Claim interpretation state:\n" + canonical_json(claim_states[:12]) + "\n\n")
        version_label = ("Structured knowledge versions:" if self.evidence_only or automatic_refs or self.local_submission else
                         "Structured knowledge versions (use these for knowledge_refs):")
        return ResearchToolOutput(preface + note.to_markdown() + "\n\n" + version_label + "\n"
                                  + canonical_json(references), ok=True)

    def _missing_knowledge_identity(self, identity: str) -> str:
        assert self.store is not None
        hints: list[KnowledgeHit] = (
            self.store.search(identity[:16], project=self.project, session_id=self.session_id, depth=0, limit=3)
            if len(identity) >= 24 else [])
        suggestion = ("\nPossible exact ids (not read or selected; verify with knowledge_read):\n" +
            "\n".join(canonical_json({"title": hit.version.value.title, "read_request": {
                "tool": "knowledge_read", "args": {"id": hit.version.value.id, "revision": hit.version.revision}}})
                for hit in hints)) if hints else ""
        return ("ERROR: requested knowledge identity was not found at the requested version. "
                "Copy an exact id and revision from knowledge_search; do not guess or shorten it." + suggestion)

    def knowledge_commit(self, args: dict[str, Any]) -> ResearchToolOutput:
        """The common tool dispatcher owns this effect; the repository only commits."""
        if self.store is None or isinstance(self.store, StagedKnowledgeStore):
            return ResearchToolOutput("ERROR: durable knowledge commit requires the authoritative store", ok=False)
        try:
            raw = args.get("changes")
            if not isinstance(raw, list) or not raw:
                raise ValueError("changes must be a nonempty list of {value, expected_revision}")
            mutations: list[KnowledgeMutation] = []
            access = KnowledgeAccess(self.project, self.session_id, self.store.owner_id)
            for row in raw:
                if not isinstance(row, dict) or set(row) != {"value", "expected_revision"}:
                    raise ValueError("each change needs value and expected_revision")
                value = KnowledgeObject.from_dict(row["value"])
                from codey.knowledge.model import KnowledgeVersion

                if not access.allows(KnowledgeVersion(value, 1, "", "")):
                    raise ValueError("knowledge scope mismatch")
                old = self.store.repository.read(value.id)
                if old is not None and not access.allows(old):
                    raise ValueError("knowledge scope mismatch")
                mutations.append(KnowledgeMutation(value, row["expected_revision"]))
            commit_id = str(args.get("commit_id") or "").strip()
            if not commit_id:
                raise ValueError("commit_id required")
            identity = f"tool:{self.session_id}:{commit_id}"
            receipt = self.store.repository.committed(identity, mutations)
            if receipt is None:
                pending = {(m.value.id, m.expected_revision + 1) for m in mutations}
                for mutation in mutations:
                    for ref in mutation.value.references:
                        if (ref.target, ref.revision) not in pending and self.store.repository.read(ref.target, ref.revision) is None:
                            return ResearchToolOutput(
                                "No changes committed. A reference target is missing. "
                                "Read its exact version before resubmitting the complete commit.\n"
                                + self._missing_knowledge_identity(ref.target), ok=False)
                for mutation in mutations:
                    value = mutation.value
                    if value.kind == "source":
                        url = str(value.provenance.get("url") or "")
                        old = self.store.repository.read(value.id)
                        unchanged_content = old and old.value.content == value.content and old.value.provenance == value.provenance
                        if not unchanged_content and (
                            self.ledger.source_record_for_url(url) is None or value.content != self.ledger.source_text_for_url(url)
                        ):
                            raise ValueError("source content must match an opened source")
            receipt = self.store.commit_knowledge(identity, mutations, changes=self.changes,
                                                   session_id=self.session_id, project=self.project)
            return ResearchToolOutput(canonical_json({"commit_id": commit_id, "versions": receipt}), ok=True)
        except (ValueError, TypeError, KeyError) as exc:
            return ResearchToolOutput(f"ERROR: {exc}", ok=False)

    def save_finding(self, args: dict[str, Any]) -> ResearchToolOutput:
        """Deterministic organization of one explicit, unreviewed interpretation."""
        from codey.research.findings import save_finding

        return save_finding(self, args)

    def save_inference(self, args: dict[str, Any]) -> ResearchToolOutput:
        from codey.research.references import save_inference

        return save_inference(self, args)

    def research_plan(self, questions: object, *, question_details: object = None, task: str = "",
                      schema_version: int = 1) -> ResearchToolOutput:
        from codey.research.questions import question_plan

        observation: dict[str, Any]
        try:
            if schema_version in {2, 3, 4}:
                from codey.research.plan_contract import compact_plan

                if question_details is not None or self.ledger.questions:
                    raise ValueError("compact plans register once and do not accept question_details")
                observation = compact_plan(questions, task, submission_mode="inline" if schema_version >= 3 else "select",
                                           schema_version=3 if schema_version == 4 else 2)
                planned = question_plan([row["text"] for row in observation["questions"]])
                self.ledger.questions = planned
                return ResearchToolOutput(canonical_json({"questions": [
                    {"question_ref": f"q{index}", "question": text} for index, text in enumerate(planned, 1)],
                    "next": "Read the original sources for the current question, then explicitly submit its supported answer or gap."}),
                    read_observation=observation, ok=True)
            planned = question_plan(questions, self.ledger.questions)
            observation = {"questions": list(planned)}
            if question_details is not None:
                from codey.research.local_scope import question_details as validate_details

                observation["question_details"] = validate_details(question_details, planned, task)
            self.ledger.questions = planned
            return ResearchToolOutput(canonical_json({"questions": [
                {"question_ref": f"q{index}", "question": text} for index, text in enumerate(planned, 1)],
                **({"question_details": observation["question_details"]} if question_details is not None else {}),
                "next": "Investigate these questions; final coverage must answer or explain the gap for every question. "
                        "A recorded plan is not completed research."}), read_observation=observation, ok=True)
        except ValueError as exc:
            return ResearchToolOutput(f"ERROR: {exc}", ok=False)

    def knowledge_write(self, args: dict[str, Any], *, finding_id: str = "", locator: str = "",
                        evidence_locators: tuple[str, ...] = (),
                        evidence_context: ResearchLedger | None = None) -> ResearchToolOutput:
        if self.store is None:
            return ResearchToolOutput("ERROR: knowledge store is unavailable", ok=False)
        existing_id, existing_note, updating, identity_error = _resolve_write_target(self.store, args)
        if identity_error:
            return ResearchToolOutput(identity_error, ok=False)
        note_type, title, body, basis_error = _validate_write_basis(args, existing_note)
        if basis_error:
            return ResearchToolOutput(basis_error, ok=False)

        ownership_error = _validate_write_ownership(existing_note, self.session_id, self.project)
        if ownership_error:
            return ResearchToolOutput(ownership_error, ok=False)

        sources, sources_error = _prepare_write_sources(self, args, existing_note, updating, note_type)
        if sources_error:
            return ResearchToolOutput(sources_error, ok=False)
        if note_type in _CITED_TYPES and any(_looks_like_url(source) for source in sources) and not args.get("evidence"):
            return ResearchToolOutput(
                'ERROR: sourced findings require explicit evidence=[{"claim":"supported conclusion",'
                '"source_url":"opened URL","excerpt":"exact contiguous source text","stance":"supports"}]. '
                'Use source_search to locate a passage, then copy it exactly. '
                'A URL alone is not evidence; no inferred quote or supporting claim was saved.', ok=False)
        evidence_context = evidence_context if evidence_context is not None else self.ledger
        evidence_preparation = evidence_context.prepare_evidence_items(
            args.get("evidence"),
            fallback_sources=sources,
            fallback_claim=title,
            fallback_body=body,
            note_type=note_type,
        )
        if evidence_preparation.error:
            return ResearchToolOutput(f"ERROR: {evidence_preparation.error}", ok=False)
        if locator:
            evidence_preparation = replace(evidence_preparation, items=tuple(
                replace(item, locator=locator) for item in evidence_preparation.items))
        if evidence_locators:
            evidence_preparation = replace(evidence_preparation, items=tuple(
                replace(item, locator=selected) for item, selected in
                zip(evidence_preparation.items, evidence_locators, strict=True)))
        relations, relation_warnings = _prepare_write_relations(args, existing_note)
        status = _resolve_write_status(args, existing_note)
        tags = (
            _as_str_list(args.get("tags"))
            if "tags" in args
            else list(existing_note.tags if existing_note is not None else [])
        )
        note = _build_write_note(
            args,
            existing_note,
            existing_id,
            note_type,
            title,
            body,
            sources,
            relations,
            tags,
            status,
            self.session_id,
            self.project,
        )
        if finding_id:
            note.id = finding_id
        from codey.research.knowledge_archive import note_knowledge

        try:
            commit_id, mutations = note_knowledge(note, evidence_context, evidence_preparation, self.store.repository,
                                                 conditions=args.get("conditions"))
        except (ValueError, TypeError) as exc:
            return ResearchToolOutput(f"ERROR: {exc}", ok=False)
        rel = self.store.publish_note(note, commit_id, mutations, changes=self.changes)
        model_text = _finalize_write_note(
            self,
            note,
            note_type,
            evidence_preparation,
            updating,
            relation_warnings,
            rel,
        )
        versions = [{"id": mutation.value.id, "revision": mutation.expected_revision + 1,
                     "kind": mutation.value.kind, "origin": mutation.value.origin,
                     "status": mutation.value.status, "interpretation_review": mutation.value.interpretation_review}
                    for mutation in mutations]
        versions.sort(key=lambda row: 0 if row["kind"] in {"claim", "inference", "question"} else 1)
        answer_refs = [{"id": row["id"], "revision": row["revision"]} for row in versions
                       if row["kind"] in {"claim", "inference", "question"}][:6]
        if answer_refs and not self.evidence_only and not self.finding_report:
            model_text += ("\nAnswer reference candidates (copy only versions actually used into done.knowledge_refs):\n"
                           + canonical_json({"knowledge_refs": answer_refs}))
        model_text += "\nStructured knowledge versions:\n" + canonical_json(versions[:24])
        model_text += ("\nFor knowledge_read use these object ids and revisions, not note_id."
                       if self.evidence_only or self.finding_report else
                       "\nFor knowledge_read and done.knowledge_refs use these object ids and revisions, not note_id.")
        if self.finding_report and not self.evidence_only:
            model_text += ("\nCite only adopted findings returned by save_finding; "
                           "no manual answer-reference copy is needed. Keep numbered source citations in the report.")
        model_text += "\nTo update this note, knowledge_write.id must be its exact note_id above, not a claim/source/evidence id."
        return ResearchToolOutput(model_text, ok=True)

    def knowledge_link(self, src: str, dst: str, kind: str = "relates") -> ResearchToolOutput:
        if self.store is None:
            return ResearchToolOutput("ERROR: knowledge store is unavailable", ok=False)
        src = (src or "").strip()
        dst = (dst or "").strip()
        if not src or not dst:
            return ResearchToolOutput("ERROR: knowledge_link needs src and dst", ok=False)
        result = self.store.link(src, dst, (kind or "relates").strip().lower(), changes=self.changes)
        if result.ok and result.created:
            self.links_created += 1
        return ResearchToolOutput(result.model_text, ok=result.ok)

    def _source_problem(self, sources: list[str]) -> str | None:
        urls = [s for s in sources if _looks_like_url(s)]
        if not urls:
            return "a source note must cite the url of a page you opened"
        unopened = [u for u in urls if u not in self.sources_read]
        if unopened:
            if all(u in self.search_result_urls for u in unopened):
                return "NEEDS_OPEN: open the source before saving this source note: " + ", ".join(unopened[:3])
            return "cite only pages you actually opened; you did not open: " + ", ".join(unopened[:3])
        return None

    def _record_failure(self, area: str, action: str, error: object, *, url: str = "") -> None:
        if self.diagnostics is not None:
            with contextlib.suppress(Exception):
                recorder = getattr(self.diagnostics, "record", None)
                if callable(recorder):
                    recorder(area, action, error, url=url, model=getattr(self.search, "name", ""))

    def _provenance_problem(self, note_type: str, sources: list[str]) -> str | None:
        if not sources:
            opened = sorted(self.sources_read)[:6]
            return (
                f"a {note_type} must cite at least one source you actually read. "
                "Supply sources=[opened URL] and evidence=[{claim:the supported conclusion,"
                "source_url:the same URL,excerpt:exact source text,stance:supports}]. "
                + ("Already opened URLs: " + ", ".join(opened) + ". " if opened else "Open a source page first. ")
                + "Do not change a sourced finding to hypothesis to bypass its missing citation."
            )
        unread_urls = [s for s in sources if _looks_like_url(s) and s not in self.sources_read]
        if unread_urls:
            if all(u in self.search_result_urls for u in unread_urls):
                return "NEEDS_OPEN: open the source before saving this note: " + ", ".join(unread_urls[:3])
            return "cite only pages you actually opened; you did not open: " + ", ".join(unread_urls[:3])
        ungrounded = [s for s in sources if not _looks_like_url(s) and s not in self.grounded_ids]
        if ungrounded:
            return "cite only sources you read; these are not grounded: " + ", ".join(ungrounded[:3])
        return None


def _resolve_write_target(
    store: KnowledgeStore,
    args: dict[str, Any],
) -> tuple[str, KnowledgeNote | None, bool, str | None]:
    existing_id = str(args.get("id") or "").strip()
    if existing_id and not is_safe_id(existing_id):
        return ("", None, False, "ERROR: invalid note id")
    existing_note = store.read_note(existing_id) if existing_id else None
    updating = existing_note is not None
    if existing_id and not updating:
        return ("", None, False, "ERROR: knowledge_write.id does not identify an existing note; no new note was created. "
                "For a new finding omit id. For a note update copy the exact note_id returned by knowledge_write; "
                "a structured claim/source/evidence id is not a note_id. Use knowledge_commit to revise structured objects.")
    return (existing_id, existing_note, updating, None)


def _validate_write_basis(
    args: dict[str, Any],
    existing_note: KnowledgeNote | None,
) -> tuple[str, str, str, str | None]:
    note_type = str(
        args.get("type") or (existing_note.type if existing_note is not None else "note")
    ).strip().lower()
    if note_type not in NOTE_TYPES:
        return ("", "", "", f"ERROR: unknown note type '{note_type}'; use one of {', '.join(NOTE_TYPES)}")
    title = str(args.get("title") or "").strip()
    body = str(args.get("body") or "").strip()
    if not title or not body:
        return ("", "", "", "ERROR: knowledge_write needs both a title and a body")
    return (note_type, title, body, None)


def _validate_write_ownership(
    existing_note: KnowledgeNote | None,
    session_id: str,
    project: str,
) -> str | None:
    if existing_note is not None:
        if existing_note.session_id and session_id and existing_note.session_id != session_id:
            return "ERROR: note belongs to another session"
        if existing_note.project and project and existing_note.project != project:
            return "ERROR: note belongs to another project"
    return None


def _format_write_problem(problem: str | None) -> str | None:
    if problem:
        return problem if problem.startswith("NEEDS_OPEN:") else f"ERROR: {problem}"
    return None


def _prepare_write_sources(
    tools: ResearchTools,
    args: dict[str, Any],
    existing_note: KnowledgeNote | None,
    updating: bool,
    note_type: str,
) -> tuple[list[str], str | None]:
    sources: list[str] = (
        _as_str_list(args.get("sources"))
        if "sources" in args
        else list(existing_note.sources if existing_note is not None else [])
    )
    # A new note can catalogue the URLs the caller already supplied on its
    # evidence items. This copies explicit locators, never invents evidence.
    if "sources" not in args and existing_note is None and isinstance(args.get("evidence"), list):
        sources = list(dict.fromkeys(
            item["source_url"].strip() for item in args["evidence"]
            if isinstance(item, dict) and isinstance(item.get("source_url"), str) and item["source_url"].strip()
        ))
    validating_sources = not updating or "sources" in args
    if note_type == "source":
        problem = (
            tools._source_problem(sources)
            if validating_sources
            else (None if sources else "a source note must cite the url of a page you opened")
        )
        error = _format_write_problem(problem)
        if error:
            return ([], error)
    elif note_type in _CITED_TYPES:
        problem = (
            tools._provenance_problem(note_type, sources)
            if validating_sources
            else (None if sources else f"a {note_type} note must cite at least one opened source URL")
        )
        error = _format_write_problem(problem)
        if error:
            return ([], error)
    return (sources, None)


def _prepare_write_relations(
    args: dict[str, Any],
    existing_note: KnowledgeNote | None,
) -> tuple[list[dict[str, Any]], list[str]]:
    if "relations" in args:
        return clean_relations(args.get("relations"))
    return (
        list(existing_note.relations if existing_note is not None else []),
        [],
    )


def _resolve_write_status(args: dict[str, Any], existing_note: KnowledgeNote | None) -> str:
    status = str(
        args.get("status")
        if "status" in args
        else (existing_note.status if existing_note is not None else "active")
    ).strip().lower()
    if status not in NOTE_STATUSES:
        status = "active"
    return status


def _build_write_note(
    args: dict[str, Any],
    existing_note: KnowledgeNote | None,
    existing_id: str,
    note_type: str,
    title: str,
    body: str,
    sources: list[str],
    relations: list[dict[str, Any]],
    tags: list[str],
    status: str,
    session_id: str,
    project: str,
) -> KnowledgeNote:
    return KnowledgeNote.create(
        type=note_type,
        title=title,
        body=body,
        id=existing_id or None,
        tags=_merge_relation_tags(tags, relations),
        sources=sources,
        aliases=(
            _as_str_list(args.get("aliases"))
            if "aliases" in args
            else list(existing_note.aliases if existing_note is not None else [])
        ),
        relations=relations,
        open_questions=(
            _as_str_list(args.get("open_questions"))
            if "open_questions" in args
            else list(existing_note.open_questions if existing_note is not None else [])
        ),
        confidence=(
            _as_float(args.get("confidence"))
            if "confidence" in args
            else (existing_note.confidence if existing_note is not None else None)
        ),
        status=status,
        retrieved_at=(
            _as_opt_str(args.get("retrieved_at"))
            if "retrieved_at" in args
            else (existing_note.retrieved_at if existing_note is not None else None)
        ),
        valid_until=(
            _as_opt_str(args.get("valid_until"))
            if "valid_until" in args
            else (existing_note.valid_until if existing_note is not None else None)
        ),
        session_id=existing_note.session_id if existing_note is not None else session_id,
        project=existing_note.project if existing_note is not None else project,
        created=existing_note.created if existing_note is not None else "",
    )


def _finalize_write_note(
    tools: ResearchTools,
    note: KnowledgeNote,
    note_type: str,
    evidence_preparation: EvidencePreparation,
    updating: bool,
    relation_warnings: list[str],
    rel: str,
) -> str:
    if note_type == "source":
        tools.grounded_ids.add(note.id)
    if evidence_preparation.items:
        tools.ledger.add_evidence_items(list(evidence_preparation.items), note_id=note.id)
    if updating:
        if note.id not in tools.updated_ids:
            tools.updated_ids.append(note.id)
    elif note.id not in tools.created_ids:
        tools.created_ids.append(note.id)
    output = f"saved {note_type} note id={note.id} in the knowledge database"
    if evidence_preparation.warning:
        output += f"; WARNING: {evidence_preparation.warning}"
    if relation_warnings:
        output += "; WARNING: relations: " + "; ".join(relation_warnings)
    output += (
        f"; note_id: {note.id}; storage_path: {rel} (logical export path) "
        "(do not use storage_path as note_id; pass note_id exactly to knowledge_read)"
    )
    return output


def _as_int(value: Any, default: int) -> int:
    if isinstance(value, bool):
        return default
    if isinstance(value, str) and not value.strip().isascii():
        return default
    try:
        return int(value)
    except (TypeError, ValueError, OverflowError):
        return default


def _as_float(value: Any) -> float | None:
    if isinstance(value, bool):
        return None
    try:
        number = float(value) if value is not None else None
    except (TypeError, ValueError, OverflowError):
        return None
    if number is None or not math.isfinite(number):
        return None
    return number


def _as_opt_str(value: Any) -> str | None:
    text = str(value).strip() if value not in (None, "") else ""
    return text or None


def _as_str_list(value: Any) -> list[str]:
    if isinstance(value, str):
        return [value.strip()] if value.strip() else []
    if isinstance(value, (list, tuple)):
        return [str(v).strip() for v in value if str(v).strip()]
    return []


def _merge_relation_tags(tags: list[str], relations: Sequence[object]) -> list[str]:
    """Relation endpoints become tags so the Concept Graph can weight them."""
    known = {normalize_concept(tag) for tag in tags}
    merged = list(tags)
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        src = relation.get("src")
        dst = relation.get("dst")
        if not isinstance(src, str) or not isinstance(dst, str):
            continue
        for concept in (src, dst):
            if concept not in known:
                known.add(concept)
                merged.append(concept)
    return merged


def _looks_like_url(source: str) -> bool:
    return source.lower().startswith(("http://", "https://"))


def _clip_tail(value: str, limit: int) -> str:
    text = (value or "")
    if len(text) <= limit:
        return text
    if limit <= 3:
        return text[-limit:]
    return "..." + text[-(limit - 3) :]


def clone_research_tools(
    tools: ResearchTools,
    *,
    search: object | None = None,
    diagnostics: object | None = None,
    session_id: str | None = None,
    project: str | None = None,
) -> ResearchTools:
    """Create a fresh tool facade over the same run-scoped research facts."""

    return ResearchTools(
        search=search if search is not None else tools.search,
        store=tools.store,
        changes=tools.changes,
        diagnostics=diagnostics if diagnostics is not None else tools.diagnostics,
        session_id=tools.session_id if session_id is None else session_id,
        project=tools.project if project is None else project,
        sources_read=tools.sources_read,
        search_result_urls=tools.search_result_urls,
        grounded_ids=tools.grounded_ids,
        created_ids=tools.created_ids,
        updated_ids=tools.updated_ids,
        links_created=tools.links_created,
        ledger=tools.ledger,
    )

source_snapshot.codey/operations/task_execution.py:
"""Production tool execution for the unified kernel (operations layer).

Project tools reuse the coding guards and readers (path safety, command
policy, shell approval surface); Research tools reuse ResearchTools, the
source gateway, and the evidence ledger. Completion facts come only from
successful tool results and ledger
state, never from substring matching or model-supplied parameters.
"""

from __future__ import annotations

import contextlib
import copy
import json
from dataclasses import dataclass, replace
from pathlib import Path
from typing import TYPE_CHECKING, Any

from codey.research.ledger import ResearchLedger
from codey.research.ledger_receipts import ledger_observation, source_search_observation
from codey.runtime.core.models import ToolCall, ToolResult

if TYPE_CHECKING:
    from codey.agents.tools import AgentToolFns
    from codey.research.tools import ResearchTools


def close_research_tools(tools: Any) -> None:
    """Release an owned search session without masking the task outcome."""
    close = getattr(getattr(tools, "search", None), "close", None)
    if callable(close):
        with contextlib.suppress(Exception):
            close()


def build_research_tools(deps: Any, *, session_id: str, project: str) -> ResearchTools:
    """Build the execution resources; configuration errors propagate to entry."""
    from codey.knowledge.changes import KnowledgeChanges
    from codey.research.tools import ResearchTools

    knowledge_store = getattr(deps, "knowledge_store", None)
    search_factory = getattr(deps, "search_factory", None)
    if search_factory is None:
        from codey.research.search_factory import default_research_search_provider

        search_factory = default_research_search_provider
    search = search_factory()
    try:
        return ResearchTools(
            search=search, store=knowledge_store,
            changes=KnowledgeChanges(root=knowledge_store.root) if knowledge_store is not None else None,
            diagnostics=None, session_id=session_id, project=project,
        )
    except BaseException:
        close = getattr(search, "close", None)
        if callable(close):
            with contextlib.suppress(Exception):
                close()
        raise


def effective_project_profile(permission_profile: object) -> str:
    """Project-guard profile shared by execution and shell approval.

    The Research profile controls research context and source tools. A
    project tool still needs the coding path/command guard; TaskPolicy
    has already authorized the individual project capability. Approval
    must evaluate with exactly this profile, never a hardcoded duplicate.
    """
    return "coding_writer" if str(permission_profile or "") == "research" else str(
        permission_profile or "coding_writer")


def _tool_result(call: ToolCall, outcome: Any) -> ToolResult:
    audit = dict(getattr(outcome, "audit", {}) or {})
    # Tool implementations cannot classify a request as a runtime guard refusal.
    audit.pop("execution_disposition", None)
    if call.name == "edit":
        changed = getattr(outcome, "changed", False)
        audit["changed"] = changed if type(changed) is bool else False
    return ToolResult(
        ok=outcome.ok is True, call=call, model_text=str(outcome.model_text or ""),
        truncated=bool(getattr(outcome, "truncated", False)),
        presentation=dict(getattr(outcome, "presentation", {}) or {}),
        audit=audit,
        canonical=dict(getattr(outcome, "canonical", {}) or {}),
    )


@dataclass(frozen=True)
class ProjectPolicyCheck:
    denied: bool
    message: str = ""
    approval_required: bool = False
    reason_code: str = ""


class ExecutionDelegate:
    """Real guards + real tools behind the kernel's policy snapshot."""

    def __init__(
        self,
        *,
        session: Any = None,
        project_path: Any = None,
        tool_fns: AgentToolFns | None = None,
        research_tools: Any = None,
        permission_profile: str = "coding_writer",
        approval_available: bool = False,
        change_tracker: Any = None,
        managed_outputs: Any = None,
        session_id: str = "",
        run_id: str = "",
        frozen_specs: dict[str, Any] | None = None,
        custom_executors: dict[str, Any] | None = None,
        research_scope: Any = None,
    ) -> None:
        self.session = session
        self.project_path: Path | None = Path(str(project_path)).expanduser() if project_path else None
        if self.project_path is not None and not self.project_path.is_dir():
            self.project_path = None
        self.tool_fns: AgentToolFns | None = tool_fns
        self.research_tools = research_tools
        self.permission_profile = (permission_profile or "coding_writer")
        self.approval_available = approval_available
        self.change_tracker = change_tracker
        self.managed_outputs = managed_outputs
        self.session_id = session_id
        self.run_id = run_id
        # 本轮冻结绑定：非 None 时解析/执行不再查询实时注册表。
        self._frozen_specs = frozen_specs
        self._custom_executors = custom_executors
        self._research_scope = research_scope
        if self.tool_fns is None and self.project_path is not None:
            from codey.agents.tools import build_project_tool_fns

            self.tool_fns = build_project_tool_fns(
                state_home=managed_outputs.root.parent if managed_outputs is not None else None,
            )

    def _resolve_spec(self, name: str) -> Any:
        lowered = (name or "").strip().lower()
        if self._frozen_specs is not None:
            return self._frozen_specs.get(lowered)
        try:
            from codey.toolchain.tool_spec import spec_for_tool
        except Exception:
            return None
        try:
            return spec_for_tool(lowered)
        except Exception:
            return None

    def _resolve_custom_executor(self, name: str) -> Any:
        lowered = (name or "").strip().lower()
        if self._custom_executors is not None:
            return self._custom_executors.get(lowered)
        try:
            from codey.toolchain.tool_spec import custom_executor_for
        except Exception:
            return None
        try:
            return custom_executor_for(lowered)
        except Exception:
            return None

    def handles(self, name: str) -> bool:
        spec = self._resolve_spec(name)
        if spec is None:
            return False
        if spec.executor == "receipt":
            return bool(self.session is not None)
        if spec.executor == "project":
            return self.project_path is not None and self.tool_fns is not None
        if spec.executor in {"source", "knowledge"}:
            return bool(self.research_tools is not None)
        try:
            if self._resolve_custom_executor(name or "") is not None:
                return True
        except Exception:
            pass
        return False

    def execute(self, call: ToolCall, *, turn: int = 0,
                tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        try:
            spec = self._resolve_spec(name)
            executor = spec.executor if spec is not None else ""
        except Exception:
            executor = ""
        if executor == "receipt":
            from codey.operations.tool_result_reader import read_tool_result

            result = read_tool_result(self, call)
            return result, result.ok, None
        if executor == "project":
            return self._execute_project(call)
        if executor in {"source", "knowledge"}:
            if not self._reserve_research_acquisition(name, turn, tool_index):
                return ToolResult(ok=False, call=call, model_text="ERROR: research acquisition budget exhausted"), False, None
            return self._execute_research(call, turn=turn, tool_index=tool_index)
        # Third-task tools run via the frozen turn binding when present,
        # otherwise the live registry.
        try:
            fn = self._resolve_custom_executor(name)
        except Exception:
            fn = None
        if callable(fn):
            try:
                produced = fn(call)
            except Exception as exc:
                result = ToolResult(ok=False, call=call, model_text=f"ERROR: {exc or 'tool failed'}")
                return result, False, None
            if not isinstance(produced, ToolResult):
                result = ToolResult(ok=False, call=call, model_text="ERROR: executor must return a structured ToolResult")
                return result, False, None
            return produced, produced.ok, None
        result = ToolResult(ok=False, call=call, model_text=f"ERROR: no production executor for {name or '?'}")
        return result, False, None

    def _policy_check(self, call: ToolCall) -> ProjectPolicyCheck:
        """Keep machine-readable denial separate from its explanation."""

        spec = self._resolve_spec(call.name)
        if spec is None:
            return ProjectPolicyCheck(True, "tool definition unavailable", False)
        if self.session is None:
            return ProjectPolicyCheck(True, "task session unavailable", False)
        if not self.session.policy.allows(spec.grant):
            return ProjectPolicyCheck(True, f"task policy denied {call.name}", False)
        if spec.executor != "project":
            return ProjectPolicyCheck(False, "", False)
        if self.project_path is None:
            return ProjectPolicyCheck(True, "no associated project", False)
        try:
            from codey.agents.tool_execution import (
                evaluate_tool_call_policy_for,
                policy_asks_user,
                policy_denied,
            )
        except Exception as exc:
            return ProjectPolicyCheck(True, f"policy unavailable: {exc}", False)
        try:
            runtime_name = {"list_dir": "ls", "read_file": "read", "grep": "search",
                            "find_references": "references"}.get(call.name, call.name)
            decision, _replay = evaluate_tool_call_policy_for(
                ToolCall(runtime_name, dict(call.args or {}), call_id=call.call_id),
                project=self.project_path,
                permission_profile=self._project_permission_profile(),
                approval_available=self.approval_available,
                phase="writer",
                shell=self.session.shell,
            )
        except Exception as exc:
            return ProjectPolicyCheck(True, f"policy error: {exc}", False)
        if decision is not None and policy_denied(decision):
            reason = str(getattr(decision, "reason", "") or getattr(decision, "reason_code", "") or "denied")
            display = decision.display
            if reason == "command_not_allowed" and not self.session.policy.allows("shell.approval"):
                display = ("This task mode cannot request shell approval. Use an interactive coding task "
                           "with command approvals enabled, or use an allowed verification command.")
            elif reason == "command_not_allowed":
                display += " Submit this command on its own in an interactive task to request approval."
            return ProjectPolicyCheck(True, f"project guard denied {call.name}: {reason}; {display}", False, reason)
        try:
            if (call.name or "") == "shell" and policy_asks_user(decision):
                return ProjectPolicyCheck(True, "shell requires user approval", True)
        except Exception:
            pass
        return ProjectPolicyCheck(False, "", False)


    def _project_permission_profile(self) -> str:
        return effective_project_profile(self.permission_profile)

    def _execute_project(self, call: ToolCall) -> tuple[ToolResult, bool, int | None]:
        if self.project_path is None:
            return ToolResult(ok=False, call=call, model_text="ERROR: project path unavailable"), False, None
        if self.tool_fns is None:
            return ToolResult(ok=False, call=call, model_text="ERROR: project tools unavailable"), False, None
        project_path = self.project_path
        check = self._policy_check(call)
        if check.denied:
            from codey.operations.kernel_result import policy_denial_result

            result = policy_denial_result(call, check.message, reason_code=check.reason_code)
            return result, False, None
        name = (call.name or "").strip().lower()
        runtime_name = {"list_dir": "ls", "read_file": "read", "grep": "search",
                        "find_references": "references"}.get(name, name)
        try:
            if runtime_name in {"ls", "read", "search", "references"}:
                from codey.agents.tool_execution import execute_information_tool_call

                outcome = execute_information_tool_call(
                    project_path, self.tool_fns,
                    ToolCall(runtime_name, dict(call.args or {})),
                )
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, None
            if name == "edit":
                outcome = self._execute_edit(call)
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, None
            if name == "run":
                from dataclasses import replace

                from codey.toolchain.command_output import output_tail, tail_lines

                tail = tail_lines((call.args or {}).get("output_tail_lines"))
                outcome = self.tool_fns.execute_run_command(
                    project_path, str((call.args or {}).get("path", ".") or "."),
                    str((call.args or {}).get("command", "") or ""),
                    permission_profile=self._project_permission_profile(), phase="writer",
                    tool_id=str(getattr(call, "call_id", "") or ""),
                )
                if tail is not None:
                    outcome = replace(outcome, model_text=f"Exit code: {outcome.exit_code}\n" + output_tail(outcome.model_text, tail),
                                      presentation={**outcome.presentation, "output_tail_lines": tail})
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, getattr(outcome, "exit_code", None)
        except Exception as exc:
            result = ToolResult(ok=False, call=call, model_text=f"ERROR: {exc}")
            return result, False, None
        result = ToolResult(ok=False, call=call, model_text=f"ERROR: unsupported project tool {name}")
        return result, False, None

    def _execute_edit(self, call: ToolCall) -> Any:
        from codey.agents.protocol import canonical_project_path
        from codey.agents.tool_execution import read_before_edit_outcome
        from codey.toolchain.runtime import EditBlock, ToolOutcome, safe_join

        if self.project_path is None:
            return ToolOutcome.error("project path unavailable")
        if self.tool_fns is None:
            return ToolOutcome.error("project tools unavailable")
        project_path = self.project_path
        args = dict(call.args or {})
        path = str(args.get("path", "") or "")
        try:
            canonical = canonical_project_path(project_path, path)
            safe_join(project_path, canonical)
        except ValueError:
            return ToolOutcome.error("workspace_escape: path escapes project root")
        if "content" in args:
            from codey.operations.edit_base import content_edit_version

            version = content_edit_version(self.session, project_path, canonical, args)
            if self.change_tracker is not None:
                self.change_tracker.capture_before(path)
            content = str(args.get("content") or "")
            if version is None:
                outcome = self.tool_fns.write_file(project_path, path, content)
            else:
                outcome = self.tool_fns.write_file(project_path, path, content, expected_version=version)
            if outcome.ok and outcome.changed and self.change_tracker is not None:
                self.change_tracker.capture_after(path)
            return outcome
        guard = read_before_edit_outcome(
            project_path, path, set(getattr(self.session, "read_files", set()) or set()),
        )
        if guard is not None:
            return guard
        # Canonical protocol only: replacements with old_string/new_string.
        # Top-level aliases are rejected before any file write.
        for legacy in ("search", "replace"):
            if legacy in args:
                return ToolOutcome.error(f"edit rejects legacy alias: {legacy}")
        replacements = args.get("replacements")
        if not isinstance(replacements, list) or not replacements:
            return ToolOutcome.error("edit needs content or exact replacements")
        blocks: list[dict[str, str]] = []
        for item in replacements:
            if not isinstance(item, dict):
                return ToolOutcome.error("edit replacement must be a mapping")
            if set(item) != {"old_string", "new_string"}:
                return ToolOutcome.error("edit replacement must be exactly old_string/new_string")
            search = str(item.get("old_string") or "")
            replace = str(item.get("new_string") or "")
            if not search:
                return ToolOutcome.error("edit replacement search must be non-empty")
            blocks.append({"old_string": search, "new_string": replace})
        if not blocks:
            return ToolOutcome.error("edit needs content or exact replacements")
        edit_blocks = [EditBlock(old_string=b["old_string"], new_string=b["new_string"]) for b in blocks]
        if self.change_tracker is not None:
            self.change_tracker.capture_before(path)
        outcome = self.tool_fns.edit_file(self.project_path, path, edit_blocks)
        if outcome.ok and outcome.changed and self.change_tracker is not None:
            self.change_tracker.capture_after(path)
        return outcome

    def _opened_result(self, call: ToolCall, opened: Any, url: str, *, ledger: ResearchLedger, turn: int,
                       tool_index: int) -> tuple[ToolResult, bool, int | None]:
        model_text = opened.model_text
        if not opened.ok:
            return ToolResult(ok=False, call=call, model_text=model_text), False, None
        if not isinstance(ledger, ResearchLedger):
            raise ValueError("successful source read requires a research ledger observation")
        observation = opened.read_observation or ledger_observation(ledger, "open", url=url)
        from codey.research.output_receipts import maybe_externalize_output

        title = next((line.removeprefix("Title: ") for line in model_text.splitlines()
                      if line.startswith("Title: ")), "")
        outcome = maybe_externalize_output(
            store=self.managed_outputs, session_id=self.session_id, run_id=self.run_id,
            permission_profile=self.permission_profile, call=call,
            output=opened.receipt_text or model_text, ok=opened.ok,
            turn=turn, tool_index=tool_index, presentation_result=title,
            model_text_override=model_text,
        )
        base = _tool_result(call, outcome)
        merged = dict(base.canonical)
        merged["research_observation"] = observation
        if opened.read_passages:
            merged["read_passages"] = list(opened.read_passages)
        result = ToolResult(
            ok=base.ok, call=base.call, model_text=base.model_text, truncated=base.truncated,
            presentation=dict(base.presentation) if isinstance(base.presentation, dict) else {},
            audit=dict(base.audit) if isinstance(base.audit, dict) else {},
            canonical=merged,
        )
        return result, True, None

    def _observation_tools(self, *, source_read: bool = False) -> Any:
        # Acquisition mutates a temporary ledger. Only the committed result
        # receipt may publish it into the run's formal projection.
        tools = copy.copy(self.research_tools)
        from codey.research.answer_contract import AnswerScope

        if hasattr(tools, "coherent_passages"):
            tools.coherent_passages = isinstance(self._research_scope, AnswerScope)
        if hasattr(tools, "evidence_only"):
            # This is a per-call presentation setting. The shared facade and
            # stored knowledge must not inherit a child phase's output contract.
            tools.evidence_only = self.session is not None and self.session.task_kind == "evidence_followup"
        if hasattr(tools, "finding_report"):
            tools.finding_report = (self.session is not None and self.session.task_kind == "research"
                                           and self.session.policy.strict_research)
        if hasattr(tools, "local_submission"):
            # Presentation follows the admitted request, including replay. Do
            # not infer a new contract from the mutable current plan here.
            tools.local_submission = self._research_scope is not None
        ledger = getattr(tools, "ledger", None)
        if isinstance(ledger, ResearchLedger):
            # A read receipt contains this acquisition alone, not stale pages
            # inherited from the pre-call projection. Other tools need context.
            with self.session.projection_lock if self.session is not None else contextlib.nullcontext():
                tools.ledger = ResearchLedger() if source_read else ledger.clone()
            if hasattr(tools, "sources_read"):
                tools.sources_read = {url for source in ledger.opened_sources
                                      for url in (source.requested_url, source.final_url)}
            if hasattr(tools, "search_result_urls"):
                tools.search_result_urls = {hit.url for search in ledger.searches for hit in search.results}
        return tools

    def _reserve_research_acquisition(self, name: str, turn: int, tool_index: int) -> bool:
        if self.session is not None and self.session.research_acquisition_limits is not None:
            category = "search" if name == "web_search" else "open" if name in {
                "open_url", "open_result", "reopen_source", "open_hit"} else ""
            if category:
                with self.session.projection_lock:
                    slots = self.session.research_acquisition_slots
                    limit = self.session.research_acquisition_limits[0 if category == "search" else 1]
                    # Rebuilt from receipts on restore, plus in-flight slots.
                    # Failed acquisitions consume budget too.
                    previous = {key for key, kind in slots.items() if kind == category}
                    if (turn, tool_index) not in previous and len(previous) >= limit:
                        return False
                    slots[(turn, tool_index)] = category
        return True

    def _research_call_denial(self, call: ToolCall) -> tuple[ToolResult, bool, int | None] | None:
        from codey.operations.kernel_result import policy_denial_result
        from codey.research.local_scope import ResearchScope, current_scope, validate_scope_call
        from codey.research.questions import QUESTION_BOUND_TOOLS, question_ref, requires_question_ref

        try:
            if self._research_scope is not None:
                from codey.research.answer_contract import AnswerScope, digest

                scope = self._research_scope
                if isinstance(scope, AnswerScope):
                    if scope.task_digest != digest(self.session.task_text):
                        raise ValueError("research scope belongs to another task")
                else:
                    actual = current_scope(self.session, repair=scope if scope.replaces else None)
                    if not isinstance(actual, ResearchScope) or (actual.plan_digest, actual.unit_ref, actual.replaces) != (scope.plan_digest, scope.unit_ref, scope.replaces):
                        raise ValueError("research scope is stale")
                    validate_scope_call(scope, call.name, call.args)
            if call.name in QUESTION_BOUND_TOOLS:
                question_ref(call.args, self.research_tools.ledger, required=requires_question_ref(self.session))
        except ValueError as exc:
            return policy_denial_result(call, str(exc), reason_code="research_question_required"), False, None
        return None

    def _execute_research(self, call: ToolCall, *, turn: int = 0,
                          tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        if name == "prepare_knowledge_revision":
            from codey.research.revision_tools import preparation_result

            result = preparation_result(self.session, self._research_scope, call)
            return result, result.ok, None
        return self._execute_research_action(call, turn=turn, tool_index=tool_index)

    def _execute_research_action(self, call: ToolCall, *, turn: int = 0,
                                 tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        tools = self._observation_tools(source_read=name in {"open_url", "open_result", "reopen_source", "open_hit"})
        args = dict(call.args or {})
        try:
            denied = self._research_call_denial(call)
            if denied is not None:
                return denied
            if name == "research_plan":
                return self._record_research_plan(call, tools)
            if name == "submit_research_answer":
                return self._submit_research_answer(call, tools)
            if name == "web_search":
                from codey.research.text_args import first_text_arg

                outcome = tools.web_search(first_text_arg(args, "query"))
                canonical = {}
                ledger = getattr(tools, "ledger", None)
                if outcome.ok:
                    if not isinstance(ledger, ResearchLedger):
                        raise ValueError("successful search requires a research ledger observation")
                    canonical["research_observation"] = ledger_observation(ledger, name)
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=canonical), outcome.ok, None
            if name == "open_url":
                opened = tools.open_url(str(args.get("url") or ""), offset=args.get("offset", 0),
                                        limit=args.get("limit", 6000), pages=str(args.get("pages") or ""))
                return self._opened_result(call, opened, str(args.get("url") or ""), ledger=tools.ledger,
                                           turn=turn, tool_index=tool_index)
            if name in {"open_result", "reopen_source", "open_hit"}:
                url = self._resolve_alias_url(name, args)
                if not url:
                    field, available = {
                        "open_result": ("result_id", self.session.search_results),
                        "reopen_source": ("source_id", self.session.source_ids),
                        "open_hit": ("hit_id", self.session.hit_targets),
                    }[name]
                    detail = (f"ERROR: unknown {name} id. Use {field} from these observed ids: "
                              + ", ".join(list(available)[-12:])
                              + ". A tool result_ref or out_ artifact handle is not a source locator.")
                    return ToolResult(ok=False, call=call, model_text=detail), False, None
                target = (getattr(self.session, "hit_targets", {}) or {}).get(
                    str(args.get("hit_id") or "").lower(), {}
                ) if name == "open_hit" else dict[str, Any]()
                opened = (tools.open_url(url, offset=target.get("offset", 0),
                                         pages=target.get("pages", ""))
                          if target else tools.open_url(url))
                return self._opened_result(call, opened, url, ledger=tools.ledger, turn=turn, tool_index=tool_index)
            if name == "source_search":
                query = str(args.get("query") or "")
                url = str(args.get("url") or "")
                if not url and str(args.get("source_id") or ""):
                    url = self._resolve_alias_url("reopen_source", {"source_id": args.get("source_id")}) or ""
                outcome = tools.source_search(url, query, args.get("limit", 6))
                if outcome.ok:
                    ledger = getattr(tools, "ledger", None)
                    if not isinstance(ledger, ResearchLedger):
                        raise ValueError("successful source search requires a research ledger observation")
                    observation = ledger_observation(ledger, name)
                    text, mapping = self._build_hit_mapping(source_search_observation(observation))
                    hit_canonical: dict[str, object] = {"hit_targets": mapping, "research_observation": observation}
                    return (
                        ToolResult(ok=outcome.ok, call=call, model_text=text, canonical=hit_canonical),
                        True, None,
                    )
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), outcome.ok, None
            if name == "knowledge_search":
                from codey.research.text_args import first_text_arg

                outcome = tools.knowledge_search(first_text_arg(args, "query"), depth=args.get("depth", 1))
                search_canonical = ({"knowledge_search_empty": True}
                    if outcome.ok and getattr(outcome, "knowledge_search_empty", False) is True else {})
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text,
                                  canonical=search_canonical), outcome.ok, None
            if name == "knowledge_read":
                return self._read_research_knowledge(call, tools)
            if name == "knowledge_commit":
                return self._commit_research_knowledge(call, tools)
            if name in {"knowledge_write", "save_finding", "save_inference"}:
                return self._execute_research_write(call, tools)
            if name == "knowledge_link":
                links_before = tools.links_created
                outcome = tools.knowledge_link(str(args.get("src") or ""), str(args.get("dst") or ""),
                                            str(args.get("kind") or "relates"))
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text,
                    canonical={"knowledge_links_created": tools.links_created - links_before}), outcome.ok, None
        except Exception as exc:
            return ToolResult(ok=False, call=call, model_text=f"ERROR: {exc}"), False, None
        return ToolResult(ok=False, call=call, model_text=f"ERROR: unknown research tool {name}"), False, None

    def _commit_research_knowledge(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.answer_contract import AnswerScope

        if isinstance(self._research_scope, AnswerScope) and any(
            row.get("value", {}).get("kind") not in {"claim", "inference", "question", "entity", "observation"}
            for row in call.args.get("changes", [])
        ):
            raise ValueError("whole research knowledge_commit only accumulates explicit claims, inferences, "
                             "questions, entities or observations; answer publication owns source/evidence/answer")
        outcome = tools.knowledge_commit(call.args)
        return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), outcome.ok, None

    def _read_research_knowledge(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.answer_contract import AnswerScope
        from codey.research.questions import question_ref

        args = call.args
        identity = str(args.get("id") or "")
        outcome = tools.knowledge_read(identity, revision=args.get("revision"), question_ref=question_ref(args, tools.ledger),
                                       offset=args.get("offset", 0), limit=args.get("limit", 6000),
                                       whole_answer=isinstance(self._research_scope, AnswerScope))
        text = outcome.model_text
        if not outcome.ok and self._research_scope is not None:
            if identity in tools.ledger.read_passages:
                text = ("ERROR: this id names a read passage, not a stored knowledge object. "
                        "Use its complete text if present in read_evidence; otherwise recover its original read with "
                        "read_tool_result using read_receipt_index. Choose an answer or a gap from the actual evidence.")
            elif identity in getattr(self.session, "source_ids", {}):
                text = ("ERROR: this id is an opened-source locator, not a stored knowledge object. "
                        "Recover its original read with read_tool_result using read_receipt_index, or use an advertised "
                        "source-reading action for more text. knowledge_read needs an exact stored id and revision.")
        canonical: dict[str, Any] = {
            "research_reference_bindings": {k: v.to_dict() for k, v in tools.ledger.references.items()}} if outcome.ok else {}
        if outcome.ok and outcome.read_passages:
            canonical.update(research_observation=outcome.read_observation, read_passages=list(outcome.read_passages))
        return ToolResult(ok=outcome.ok, call=call, model_text=text, canonical=canonical), outcome.ok, None

    def _record_research_plan(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.plan_contract import frozen_plan_version, is_compact_plan_spec

        spec = self._frozen_specs.get(call.name) if self._frozen_specs is not None else None
        compact = is_compact_plan_spec(spec)
        version = frozen_plan_version(spec) if compact else 1
        args = call.args
        if compact and args.get("contract_version", version) != version:
            raise ValueError("contract_version must match the frozen entry")
        outcome = tools.research_plan(args.get("questions"), question_details=args.get("question_details"),
                                      task=str(getattr(self.session, "task_text", "")), schema_version=version)
        canonical = {"research_observation": outcome.read_observation} if outcome.ok else {}
        return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=canonical), outcome.ok, None

    def _submit_research_answer(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.knowledge.model import canonical_json
        from codey.research.answer_contract import AnswerScope, submit_answer
        from codey.research.local_scope import selection_budget, submission, submission_finding

        if isinstance(self._research_scope, AnswerScope):
            declared = submit_answer(self._research_scope, call.args)
            return ToolResult(call, "Whole answer recorded. The application will validate and publish this submission.",
                              ok=True, canonical={"research_submission": declared}), True, None

        canonical: dict[str, Any] = {}
        created_finding = None
        if self._research_scope is None:
            raise ValueError("submit_research_answer requires an original frozen research scope")
        finding = submission_finding(self._research_scope, call.args)
        if finding is not None:
            saved, ok, code = self._execute_research_write(ToolCall("save_finding", finding), tools)
            if not ok:
                if "version literal absent from selected original excerpts:" in saved.model_text:
                    from codey.research.source_literals import version_anchors

                    available = [(ref, tools.ledger.read_passages[ref].excerpt) for ref in self._research_scope.passage_refs]
                    saved = replace(saved, model_text=saved.model_text + "\n" + canonical_json({
                        "available_version_locators": version_anchors(finding["claim"], available),
                        "next": "Full windows are in read_evidence. Select one primary passage_ref and up to 3 OTHER "
                                "additional_passage_refs from the same exact source version to support the whole answer. "
                                "These number matches are locators, not semantic approval or automatic adoption."}))
                return replace(saved, call=call), False, code
            saved_ref = json.loads(saved.model_text)["finding_ref"]
            binding = tools.ledger.references[saved_ref]
            created_finding = (saved_ref, binding.object_id, binding.revision)
            canonical.update(saved.canonical)
        answer = submission(self.session, tools.ledger, self._research_scope, call.args, created_finding=created_finding)
        canonical["research_answer"] = answer
        return ToolResult(ok=True, call=call, model_text=canonical_json({
            "unit_ref": answer["unit_ref"], "state": answer["state"], "selection_recorded": True,
            **({"finding_ref": created_finding[0], "interpretation_review": "unreviewed"} if created_finding else {}),
            "report_budget": selection_budget(self.session, tools.ledger, tools.store, pending_answer=answer),
            "next": "The kernel advances the original plan or checks its parent report. No global done is needed."}),
            canonical=canonical), True, None

    def _execute_research_write(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        name, args = call.name, dict(call.args or {})
        before = len(getattr(getattr(tools, "ledger", None), "evidence_items", ()) or ())
        created_before, updated_before = set(tools.created_ids), set(tools.updated_ids)
        links_before = tools.links_created
        lowered, problem = (self._lower_finding_source(args) if name == "save_finding" else
                            (args, "") if name == "save_inference" else self._lower_knowledge_sources(args))
        if problem:
            return ToolResult(ok=False, call=call, model_text=f"ERROR: {problem}"), False, None
        outcome = (tools.save_finding(lowered) if name == "save_finding" else
                   tools.save_inference(lowered) if name == "save_inference" else tools.knowledge_write(lowered))
        if not outcome.ok:
            return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), False, None
        evidence = self._ledger_evidence(before, tools.ledger)
        evidence_canonical: dict[str, object] = {"evidence_items": evidence}
        if name in {"save_finding", "save_inference"}:
            evidence_canonical["research_reference_bindings"] = {k: v.to_dict() for k, v in tools.ledger.references.items()}
        evidence_canonical["knowledge_links_created"] = tools.links_created - links_before
        proposals: list[object] = []
        created = [item for item in tools.created_ids if item not in created_before]
        target = str(lowered.get("id") or "")
        updated = list(dict.fromkeys([item for item in tools.updated_ids if item not in updated_before] +
            ([target] if target in tools.updated_ids else [])))
        evidence_canonical["knowledge_notes"] = {
            "created": created,
            "updated": updated,
            "proposals": proposals,
        }
        affected = list(dict.fromkeys([*created, *updated]))
        self._staged_note_receipt(tools, affected, proposals, evidence_canonical)
        ledger = getattr(tools, "ledger", None)
        if isinstance(ledger, ResearchLedger) and name != "save_inference":
            evidence_canonical["research_observation"] = ledger_observation(ledger, name, evidence_start=before)
        return (
            ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=evidence_canonical),
            True, None,
        )

    @staticmethod
    def _staged_note_receipt(tools: Any, created: list[str], proposals: list[object], canonical: dict[str, object]) -> None:
        from codey.providers.response_record import json_value
        from codey.research.staging import StagedKnowledgeStore

        if isinstance(getattr(tools, "store", None), StagedKnowledgeStore):
            proposals.extend(json_value(tools.store._staged_notes[identity]) for identity in created)
            canonical["knowledge_bases"] = {identity: tools.store._staged_bases[identity] for identity in created}
            canonical["knowledge_batches"] = {
                identity: {"commit_id": batch[0], "mutations": [
                    {"value": mutation.value.to_dict(), "expected_revision": mutation.expected_revision}
                    for mutation in batch[1]]}
                for identity, batch in tools.store._staged_knowledge.items() if identity in created
            }

    def _lower_knowledge_sources(self, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
        import re

        sources = dict(getattr(self.session, "source_ids", {}) or {})

        def lower(value: object) -> tuple[str, str]:
            text = str(value or "").strip()
            key = text.lower()
            if key in sources:
                return str(sources[key]), ""
            if re.fullmatch(r"s[1-9][0-9]*", key):
                return "", f"unknown source_id: {text}"
            return text, ""

        lowered = dict(args)
        if isinstance(args.get("sources"), list):
            rows: list[str] = []
            for value in args["sources"]:
                resolved, error = lower(value)
                if error:
                    return {}, error
                rows.append(resolved)
            lowered["sources"] = rows
        if isinstance(args.get("evidence"), list):
            evidence: list[dict[str, Any]] = []
            for value in args["evidence"]:
                if not isinstance(value, dict):
                    evidence.append(value)
                    continue
                row = dict(value)
                for key in ("source_url", "source"):
                    if key in row:
                        resolved, error = lower(row[key])
                        if error:
                            return {}, error
                        row[key] = resolved
                evidence.append(row)
            lowered["evidence"] = evidence
        return lowered, ""

    def _lower_finding_source(self, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
        # The selected passage owns the source identity. An explicitly supplied
        # source is only an assertion to validate, including frozen older calls.
        if "source_ref" not in args:
            return args, ""
        reference = args.get("source_ref")
        sources = dict(getattr(self.session, "source_ids", {}) or {})
        if not isinstance(reference, str) or reference not in sources:
            return {}, "source_ref must be an exact opened source reference: " + ", ".join(sources)
        return {**args, "source_ref": sources[reference]}, ""

    def _resolve_alias_url(self, alias: str, args: dict[str, Any]) -> str:
        session = self.session
        key = {"open_result": "result_id", "reopen_source": "source_id", "open_hit": "hit_id"}.get(alias, "")
        rid = str(args.get(key, "") or "").strip().lower() if key else ""
        if not rid or session is None:
            return ""
        results = dict(getattr(session, "search_results", {}) or {})
        sources = dict(getattr(session, "source_ids", {}) or {})
        if alias == "open_hit":
            return str((getattr(session, "hit_targets", {}) or {}).get(rid, {}).get("url", "") or "")
        return str(results.get(rid, "") or sources.get(rid, "") or "")

    def _build_hit_mapping(self, observation: dict[str, Any]) -> tuple[str, dict[str, dict[str, object]]]:
        """Build hit text plus its mapping without touching the session.

        IDs consider both the live session mapping and the current batch so
        repeated IDs never collide. The caller persists the mapping in the
        receipt canonical; the single fact entry applies it to the session.
        """
        from codey.research.source_search import SourceSearchHit, render_results

        existing = dict(getattr(self.session, "hit_targets", {}) or {}) if self.session is not None else {}
        batch: dict[str, dict[str, object]] = {}
        by_target: dict[tuple[str, int, str], str] = {}
        for key, value in list(existing.items()):
            if isinstance(value, dict):
                by_target[(str(value.get("url", "")), int(value.get("offset", 0) or 0), str(value.get("pages", "")))] = key
        hit_ids = []
        counter = len(existing) + 1
        for hit in observation["hits"]:
            page = hit["page"]
            target = (observation["source_url"], 0 if page is not None else hit["offset"],
                      str(page) if page is not None else "")
            hit_id = by_target.get(target, "")
            if not hit_id:
                while f"h{counter}" in existing or f"h{counter}" in batch:
                    counter += 1
                hit_id = f"h{counter}"
                counter += 1
                by_target[target] = hit_id
            # The receipt describes this query's targets, including reused ids.
            # Otherwise the display cannot distinguish an empty result from a
            # repeat query that legitimately found the same passages.
            batch[hit_id] = {"url": target[0], "offset": target[1], "pages": target[2]}
            hit_ids.append(hit_id)
        hits = [SourceSearchHit(**hit) for hit in observation["hits"]]
        return render_results(hits, hit_ids=tuple(hit_ids)), batch

    def _ledger_evidence(self, before: int, ledger: ResearchLedger) -> list[dict[str, str]]:
        items = list(getattr(ledger, "evidence_items", ()) or [])
        fresh = items[before:] if before >= 0 else items
        evidence: list[dict[str, str]] = []
        for item in fresh:
            url = str(getattr(item, "source_url", "") or "").strip()
            excerpt = str(getattr(item, "excerpt", "") or "").strip()
            if url and excerpt:
                evidence.append({"source_url": url, "excerpt": excerpt[:600]})
        return evidence


